import { cn } from '@/lib/utils'
import { ComponentProps } from 'react'
import { useTranslation } from 'react-i18next'
import { useSession } from '@/hooks/useSession'
import { IconUsers, IconActivity, IconTrendingUp } from '@tabler/icons-react'
import { StatCard } from './StatsGrid/StatCard'

const STAT_KEYS = ['users', 'activity', 'growth'] as const
const STAT_ICONS = {
	users: { icon: IconUsers, iconColor: 'text-primary', iconBgColor: 'bg-primary/10' },
	activity: { icon: IconActivity, iconColor: 'text-blue-600', iconBgColor: 'bg-blue-100' },
	growth: { icon: IconTrendingUp, iconColor: 'text-green-600', iconBgColor: 'bg-green-100' },
} as const

export function OverviewSection({ className, ...props }: ComponentProps<'div'>) {
	const { t } = useTranslation()
	const session = useSession()
	const userName = session?.user?.name?.split(' ')[0] ?? ''

	return (
		<div className={cn('w-full flex flex-col gap-4', className)} {...props}>
			<div>
				<h1 className="text-2xl font-bold text-foreground">{t('dashboard.overviewWelcome', { name: userName })}</h1>
				<p className="text-sm text-muted-foreground">{t('dashboard.overviewSubtitle')}</p>
			</div>
			{/* TODO: Replace with real data hooks when SDK is available */}
			<div className="grid grid-cols-1 md:grid-cols-3 gap-4">
				{STAT_KEYS.map(key => {
					const meta = STAT_ICONS[key]
					return (
						<StatCard
							key={key}
							title={t(`dashboard.stats.${key}`)}
							value={0}
							icon={meta.icon}
							iconColor={meta.iconColor}
							iconBgColor={meta.iconBgColor}
						/>
					)
				})}
			</div>
		</div>
	)
}
